UPDATE `item_template` SET `description` = '搜刮附近被你杀死的生物；在队伍和地下城中有效，但无法在团队中使用。\n\n这个伙伴会加入你的外观收藏，并可供你所有角色使用。\n\n这是一个不参与战斗的伙伴。' WHERE `entry` = 57000 AND `description` = 'Loots nearby creatures you\'ve killed, will work in parties and dungeons, but is not usable in raids. \n\nThis companion is added to your Vanity Collection and is usable on all of your characters.\n\nThis is a non-combat companion.';
UPDATE `item_template` SET `description` = '这件装饰性物品会加入你的外观收藏，并可供你所有角色使用。' WHERE `entry` = 79240 AND `description` = 'This cosmetic item is added to your vanity collection and is usable on all of your characters.';
UPDATE `item_template` SET `description` = '@|cFFCC0000Seasonal Realms Exclusive|r@@|cFFCC0000赛季服务器专属|r@该物品将解锁你的赛季成就收藏。该物品让你可以在赛季期间获得赛季点数。这些点数可用于解锁专属外观！' WHERE `entry` = 97398 AND `description` = '@|cFFCC0000Seasonal Realms Exclusive|r@This item will unlock your Seasonal Achievement Collection. This item allows you to earn Seasonal Points during the season. These points can be spent to unlock exclusive cosmetics!';
UPDATE `item_template` SET `description` = '完成试炼获得的奖杯，可用来兑换奖励。\n\n可以在任何主城或起始区域与挑战大师兑换专属外观。' WHERE `entry` = 97751 AND `description` = 'A trophy earned by completing trials that can be turned in for rewards. \n\nThese can be traded to a Challenge Master for exclusive cosmetics in any capital or starting zone.';
UPDATE `item_template` SET `description` = '教你如何召唤这个伙伴。\n\n|cFFFFD100哔哔。我是你的科格斯利装置。你在法力风暴中需要帮助吗？我可以修理你的物品并出售你的财物。|r\n\n|cFFFFD100科格斯利只在法力风暴中有效。|r\n\n这是一个不参与战斗的伙伴。' WHERE `entry` = 98074 AND `description` = 'Teaches you how to summon this companion.\n\n|cFFFFD100Beep boop. I am your Cogsley device. Are you seeking assistance in the Manastorm? I can repair your items and vendor your goods.|r\n\n|cFFFFD100Cogsley only works in the Manastorm.|r\n\nThis is a non-combat companion.';
