UPDATE `item_template` SET `description` = '一套用于幻化的装饰性套装。你可以在外观收藏中查看这些装饰性套装的样子。这些套装可以从其他玩家、拍卖行或飞升商店获得。' WHERE `entry` = 295310 AND `description` = 'A Cosmetic set meant to be used with Transmogrification. You can see what Cosmetic Sets look like in the Vanity Collection. These can be obtained from other players, the auctionhouse, or the Ascension shop.';
UPDATE `item_template` SET `description` = '一位失踪寡妇的法杖……我很好奇她用它做什么。' WHERE `entry` = 352621 AND `description` = 'A lost widow\'s walking cane...I wonder what she used it for?';
UPDATE `item_template` SET `description` = '@Worldforged@这位冒险者的护甲几乎什么都不剩了，但或许还够裹住你的手腕。' WHERE `entry` = 354154 AND `description` = '@Worldforged@Barely anything remains of this adventurer\'s armor, but there might be enough left to wrap around your wrists.';
UPDATE `item_template` SET `description` = '@Worldforged@一个早已毁灭的世界的碎片，麦迪文曾把它当作奇珍收在地下室里。' WHERE `entry` = 354469 AND `description` = '@Worldforged@A piece of a long-destroyed world that Medivh kept in his cellar as a curiosity.';
UPDATE `item_template` SET `description` = '在部落进攻之前，激流堡的部队用这样的弩清除在桥边游荡的辛迪加兵力。' WHERE `entry` = 355168 AND `description` = 'Before the Horde\'s attack, Stromgarde\'s forces made use of crossbows like this one to pick off Syndicate forces who wandered within view of the bridge.';
UPDATE `item_template` SET `description` = '你不确定这到底是什么肉，也不确定自己是否想知道。' WHERE `entry` = 355199 AND `description` = 'You aren\'t sure exactly what kind of meat this actually is, and you aren\'t sure you want to know.';
UPDATE `item_template` SET `description` = '用于学习新技能；随着你升级，会定期获得。' WHERE `entry` = 383080 AND `description` = 'Used to learn new abilities, these are gained periodically as you level.';
UPDATE `item_template` SET `description` = '用于学习和提升天赋等级；10 级之后每升一级获得一次。' WHERE `entry` = 383081 AND `description` = 'Used to learn and level up talents, these are gained once per level after level 10.';
UPDATE `item_template` SET `description` = '赋予你清除并重置天赋的能力' WHERE `entry` = 383083 AND `description` = 'Gives you the power to purge and reset your Talents';
UPDATE `item_template` SET `description` = '@Worldforged@这片刀刃上有种不对劲的感觉……' WHERE `entry` = 410051 AND `description` = '@Worldforged@Something about this blade doesn\'t feel right...';
UPDATE `item_template` SET `description` = '@Worldforged@呃？他们是真的不喜欢火。' WHERE `entry` = 415004 AND `description` = '@Worldforged@Huh, they REALLY do not like fire.';
UPDATE `item_template` SET `description` = '@Worldforged@在一场战斗中遗失，一件被遗忘的海盗贪婪饰品。' WHERE `entry` = 415052 AND `description` = '@Worldforged@Lost in a battle, a trinket of forgotten pirate greed.';
UPDATE `item_template` SET `description` = '@Worldforged@用来砍树！' WHERE `entry` = 450244 AND `description` = '@Worldforged@For cutting down trees!';
UPDATE `item_template` SET `description` = '@Worldforged@别跟你的亲人分享。' WHERE `entry` = 450264 AND `description` = '@Worldforged@Do not share it with your loved ones.';
UPDATE `item_template` SET `description` = '空腔足以让任何人发狂，毫无疑问！' WHERE `entry` = 450521 AND `description` = 'Cavities can definitely enrage anyone!';
UPDATE `item_template` SET `description` = '@Worldforged@这些笔记记载了一名雄蜂在成为实验对象后逐渐陷入疯狂的过程。' WHERE `entry` = 450559 AND `description` = '@Worldforged@These notes depict a Drone\'s fall into madness while being experimented on.';
UPDATE `item_template` SET `description` = '@Worldforged@你听到剑中传来一声微弱的尖叫。' WHERE `entry` = 450641 AND `description` = '@Worldforged@You hear a faint scream from the sword.';
UPDATE `item_template` SET `description` = '@Worldforged@其中仅存一丝艾森娜的力量。' WHERE `entry` = 451047 AND `description` = '@Worldforged@Holds merely a sliver of Aessina\'s power.';
UPDATE `item_template` SET `description` = '@Worldforged@嘿，只要管用就行' WHERE `entry` = 460000 AND `description` = '@Worldforged@Hey, as long as it works';
UPDATE `item_template` SET `description` = '@Worldforged@这件投掷武器曾是「神奇四甲」收藏的一部分。别被这谐音梗骗了。它砸起人来，依然够得上一次世界巡演的分量。' WHERE `entry` = 515382 AND `description` = '@Worldforged@This throwing weapon was once part of a Fab Four collection. Don’t let the pun fool you. It still packs a hit worthy of a worldwide tour.';
UPDATE `item_template` SET `description` = '@Worldforged@提高 300% 奔跑速度' WHERE `entry` = 515537 AND `description` = '@Worldforged@Increases Racing Speed by 300%';
UPDATE `item_template` SET `description` = '@Worldforged@艾萨拉力量的隐喻式体现；而它的威力似乎也同样货真价实。' WHERE `entry` = 515623 AND `description` = '@Worldforged@A metaphorical representation of Azshara\'s strength, its power seems to be quite literal as well.';
UPDATE `item_template` SET `description` = '@Worldforged@艾尔达拉曾在这样的武器上铭刻马克里符文，以抵御来犯者、保卫城市。驱使它的魔法早已消散，但它的运作方式似乎与现代弩相差无几。' WHERE `entry` = 515625 AND `description` = '@Worldforged@Eldara inscribed Markri runes onto weapons like this one to defend the city from attackers. The enchantments animating it have long since faded, but it looks to function similarly to a modern crossbow.';
UPDATE `item_template` SET `description` = '@Worldforged@这些护肩承载着大祭司辛玛洛尔力量的微弱回响，一个至今仍令史学家困惑的谜团。' WHERE `entry` = 515626 AND `description` = '@Worldforged@These shoulderguards carry a faint echo of High Priest Zin-Malor’s power—an enigma that continues to baffle historians.';
UPDATE `item_template` SET `description` = '@Worldforged@曾经穿过这副护肩的躯体已所剩无几，但织入这破布中的持久魔法依然留存。' WHERE `entry` = 515703 AND `description` = '@Worldforged@Little remains of the body that once wore these pads, but the lingering magic woven into the tattered cloth still endures.';
UPDATE `item_template` SET `description` = '@Worldforged@小心，镜片碎了，别把玻璃碄弄进眼睛里！' WHERE `entry` = 515835 AND `description` = '@Worldforged@Watch out, the lens is broken, don\'t get glass in your eyes!';
