-- npc_text: 289
UPDATE `npc_text` SET `text0_0` = '哪一项专业技能?' WHERE `ID` = 34 AND `text0_0` = 'Which profession?';
UPDATE `npc_text` SET `text0_0` = '我能帮你什么忙吗？' WHERE `ID` = 48 AND `text0_0` = 'How may I help you?';
UPDATE `npc_text` SET `text0_0` = '哎呀，这不是个朝气蓬勃的$c嘛，无疑是被我在战场上的英勇事迹吸引来的！$B$B现在没时间讲故事了，因为有更重要的大事等着去做！所以如果你在寻找荣耀，那么今天算你走运……' WHERE `ID` = 1244 AND `text0_0` = 'Well, if it isn\'t a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you\'re looking for glory, then luck shines on you today...';
UPDATE `npc_text` SET `text0_0` = '你可以在智慧谷，葛罗玛许堡，索尔的顾问群中找到大师皮礼诺。' WHERE `ID` = 2566 AND `text0_0` = 'Master Pyreanor can be found among Thrall\'s advisors in his fortress, Grommash Hold, in the Valley of Wisdom.';
UPDATE `npc_text` SET `text0_0` = '我是一名拥有强大力量的法师，一直以来，我都潜心研究精神和记忆，这有利於学习知识和保持学会的知识。要不是我在夜晚听到一个巨大的声音说需要我的帮助，我的研究一定已经完成啦。我只在这儿待一会儿，免费为你重修天赋。接着我就得离开，而你也要选择自己的道路。' WHERE `ID` = 2673 AND `text0_0` = 'I am a mage of great power, I have spent my days studying the mind and the memory as it pertains to learning and the retention of learned abilities. I would even now be perfecting my studies if not for the great voices that came to me in the night, informing me that my services were required. I will be here for only a short time offering my ability to wipe your talents for free. Soon I will leave again, and you will once more be stuck with whatever choices you make.';
UPDATE `npc_text` SET `text0_0` = '青少年者的比赛引起冬幕节的大混乱。铁炉堡的银行是庆典的中心。' WHERE `ID` = 9690 AND `text0_0` = 'The younger races make a big fuss over Winter Veil. Ironforge\'s bank is the center of the festivities.';
UPDATE `npc_text` SET `text0_0` = '新年节庆最大的庆祝活动在月光林地进行。在雷霆崖长者高地那里的德鲁伊们将可以传送你过去。' WHERE `ID` = 9708 AND `text0_0` = 'The largest celebration of the Lunar Festival takes place in Moonglade. Druids will transport you there from the Elder Rise of Thunder Bluff.';
UPDATE `npc_text` SET `text0_0` = '去铁炉堡的秘法区并且与那里的夜精灵德鲁伊们讲话。他们能送你到月光林地参加新年节庆庆祝活动。' WHERE `ID` = 9715 AND `text0_0` = 'Go to Ironforge\'s Mystic Ward and speak with the night elf druids there. They can transport you to Moonglade to join in the Lunar Festival celebration.';
UPDATE `npc_text` SET `text0_0` = '又一个士兵往$g他:她;去荣誉堡的路上了...以库德兰的胡须为名，他们需要帮助!' WHERE `ID` = 9935 AND `text0_0` = 'Another soldier on $ghis:her; way to Honor Hold... by Kurdran\'s beard, they can use the help!';
UPDATE `npc_text` SET `text0_0` = '又一个士兵往$g他:她;去荣誉堡的路上了...以库德兰的胡须为名，他们需要帮助!' WHERE `ID` = 9991 AND `text0_0` = 'Another soldier on $ghis:her; way to Honor Hold... by Kurdran\'s beard, they can use the help!';
UPDATE `npc_text` SET `text0_0` = '什么?这是哪里?这根本不对!看看你!看看这个地方!这不在我的清单上!肯定会有非常多的文书工作...$b$b<那些哥布林在小笔记本里疯狂地写着。>$b$b看，如果你已经没有比站在那里发呆更好的事可做，你怎么不去拜访我在主要城市之一的表弟，丘比特·传播者?听说他正在处理奥格玛，暴风城，雷霆崖，铁炉堡，幽暗城和达纳苏斯的事。去吧，离开这里!' WHERE `ID` = 10635 AND `text0_0` = 'What? Where am I? This isn\'t right at all! Look at you! Look at this place! It isn\'t on my list! There\'s going to be so much paperwork...$b$b<The goblin writes frantically in a small notebook.>$b$bLook, if you\'ve got nothing better to do than stand there and stare, why don\'t you go visit my cousin, Kwee Q. Peddlefeet, in one of the major cities? Says here he\'s taking care of Orgrimmar, Stormwind, Thunder Bluff, Ironforge, the Undercity, and Darnassus. Go on, get outta here!';
UPDATE `npc_text` SET `text0_0` = '等你拜访完这个奇特的城市，或许你就会有兴趣和我们一起庆祝。新年庆典在月光林地进行;其他城市有传送点可前往庆祝。一起来加入其他的狂欢者吧!' WHERE `ID` = 10738 AND `text0_0` = 'When you\'re done visiting this exotic city, perhaps you would be interested in celebrating with us. The Lunar Festival is underway in Moonglade; the other cities have transport to the festivities. Come and join the other revelers!';
UPDATE `npc_text` SET `text0_0` = '遗忘你的法术火焰裁缝技能不是一件可以轻易决定的事情。如果你选择放弃它，你将忘记所有需要法术火焰裁缝才能制作的配方！$b$b你绝对确定吗？$B' WHERE `ID` = 10982 AND `text0_0` = 'Forgetting your skill in Spellfire Tailoring is not something to do lightly.  If you choose to abandon it you will forget all recipes that require Spellfire Tailoring to create!$b$bAre you absolutely sure?';
UPDATE `npc_text` SET `text0_0` = '如果你想要进行消防演练，这里就是了。在这附近可能会有一堆雪，不过你永远不知道何时钢架或是那些地精们会引起爆炸，对吧?' WHERE `ID` = 12117 AND `text0_0` = 'If you\'re looking to practice fire fighting, this is the place. There may be a heap of snow hereabouts, but you never know when Steelgrill or those gnomes\'ll cause an explosion, eh?';
UPDATE `npc_text` SET `text0_0` = '很高兴再次见到你，$n。希望你在俱乐部里玩的开心。' WHERE `ID` = 12971 AND `text0_0` = 'Good seein\' you again, $n.  I hope our club be treatin\' ya right.';
UPDATE `npc_text` SET `text0_0` = '嘿，$n!我希望你喜欢我们的俱乐部!' WHERE `ID` = 12973 AND `text0_0` = 'Hey, $n!  I hope you\'ve been enjoying our club!';
UPDATE `npc_text` SET `text0_0` = '欺诈者法师领主厄隆保护着第三道环。他看起来单独一人并且毫无戒备，但是别被他的外貌给欺骗了!厄隆是位强大的咒术师，控制一整群的幻魅生物。到上面把他找出来。' WHERE `ID` = 13467 AND `text0_0` = 'The trickster Mage-Lord Urom protects the third ring.  He will appear alone and defenseless, but do not be fooled by appearances!  Urom is a powerful conjurer who commands a menagerie of Phantasmal creatures.  Seek him out above.';
UPDATE `npc_text` SET `text0_0` = '你的等级还不足以参加暴风之眼的战斗。等你获得更多经验的时候再回来。' WHERE `ID` = 13578 AND `text0_0` = 'You are not yet strong enough to do battle in the Eye of the Storm. Return when you have gained more experience.';
UPDATE `npc_text` SET `text0_0` = '等等，$c...$b$b最後...一个...请求' WHERE `ID` = 13938 AND `text0_0` = 'Wait, $c....$b$bOne... final request...';
UPDATE `npc_text` SET `text0_0` = '我能帮你什么忙吗？' WHERE `ID` = 14125 AND `text0_0` = 'How may I help you?';
UPDATE `npc_text` SET `text0_0` = '<艾琳迪雅的身体轻飘飘地浮在海浪上。看来她已经死了有一断时间了。>' WHERE `ID` = 14289 AND `text0_0` = '<Allyndia\'s body bobs gently in the surf. It appears that she\'s been dead for some time.>';
UPDATE `npc_text` SET `text0_0` = '<就在你把巴瑞萨斯无生气的身体由水中转过来时，他头上致命的伤口清楚让你了解他为什么没有活下来。>' WHERE `ID` = 14290 AND `text0_0` = '<As you turn Barithras\' limp body over in the water, a brutal injury on his head makes it very apparent why he did not make it.>';
UPDATE `npc_text` SET `text0_0` = '<达蒙德的表情看起来还算是平静，身体一小部份埋在沙中。>' WHERE `ID` = 14291 AND `text0_0` = '<Dalmond\'s body looks almost peaceful, buried only slightly in the sand..>';
UPDATE `npc_text` SET `text0_0` = '<格隆达尔无助地向正在靠近的你移动，但当生命之火熄灭时他的双臂也垂了下来。>' WHERE `ID` = 14292 AND `text0_0` = '<Grondal reaches futilely towards you as you approach, but his arm collapses as life slips from him.>';
UPDATE `npc_text` SET `text0_0` = '<特伦希斯双眼的眨动逐渐停止，掩饰了他死前眼中所透露出的悲伤。>' WHERE `ID` = 14293 AND `text0_0` = '<Terenthis\' eyes stare unblinking into the distance, betraying the sorrow of his last moments.>';
UPDATE `npc_text` SET `text0_0` = '<当你走近时，你听到塞瑞利恩呼吸的喘气声。如果能很快获得治疗，或许还有活下来的机会。>' WHERE `ID` = 14297 AND `text0_0` = '<As you approach, you hear Cerellean gasp for breath. He looks to stand a chance if rescued soon.>';
UPDATE `npc_text` SET `text0_0` = '<沃科尔的身体在地上一动也不动。就在你转身要离开时，一只手伸出来抓住了你的脚踝。他还活着!>' WHERE `ID` = 14298 AND `text0_0` = '<Volcor\'s body lies motionless.  As you begin to move away, a hand reaches out and grabs your ankle. He\'s alive!>';
UPDATE `npc_text` SET `text0_0` = '<当你接近时，戈萨拉滚到他那边注视着你。你看到他脸上浮出了带着希望的笑容。>' WHERE `ID` = 14300 AND `text0_0` = '<Gershala rolls onto his side to look at you as you approach and you see a hopeful smile creep onto his face.>';
UPDATE `npc_text` SET `text0_0` = '我在精灵走前都不工作!' WHERE `ID` = 14346 AND `text0_0` = 'Me not workin\' til elfs is gone!';
UPDATE `npc_text` SET `text0_0` = '我听说旅人丰年祭是把你自己的好运分享给周遭众人的节日。$B$B我们很幸运能找到这个世界以及其中的勇敢居民，将我们的智慧与知识与他们分享应该相当适合。' WHERE `ID` = 14636 AND `text0_0` = 'I am told Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BWe are lucky to have found this world and its bold inhabitants; it is only fitting that we lend our knowledge and strength to these new-found allies.';
UPDATE `npc_text` SET `text0_0` = '人类酿的酒跟亚麻袋泡水的味道差不多，但他们的确很懂料理。旅人丰年祭?我超喜欢的!' WHERE `ID` = 14637 AND `text0_0` = 'Humans can\'t brew their way out of a tattered linen pouch, but there sure know how to cook. Pilgrim\'s Bounty? I\'m all for it!';
UPDATE `npc_text` SET `text0_0` = '一个理想的旅人丰年祭庆典所需要物资流通非常的惊人...需要这么多的稀有材料，这么多人力，成千上万的箱子装着成品被运到这里，而到处都是丰年祭餐席。$B$B老实说，我很惊讶!而且很饿...我可以闻到南瓜派的香味。你闻到那些派了吗?' WHERE `ID` = 14638 AND `text0_0` = 'The logistics involved in the optimal celebration of Pilgrim\'s Bounty are quite staggering... so many raw materials, so much labor, thousands upon thousands of crates of finished product shipped here and there and everywhere for countless Bountiful Tables.$B$BHonestly, I\'m quite impressed! And hungry... I can smell pumpkin pie. Can you smell that pie?';
UPDATE `npc_text` SET `text0_0` = '兽人跟牛头人很幸运能找到彼此，因为我们对彼此种族的力量充满钦佩与崇敬。我们很高兴跟他们一起能加入庆典。$B$B就连被遗忘者也参加了，虽然我不在乎他们是为了什么目的...' WHERE `ID` = 14642 AND `text0_0` = 'The orcs and tauren are fortunate to have found one another, for each people\'s strengths compliment the other\'s.  We are glad to join them in this celebration.$B$BEven the Forsaken partake, though to what end I am not certain...';
UPDATE `npc_text` SET `text0_0` = '旅人丰年祭是把一个人的好运分享给周遭众人的时刻。$B$B在莫高雷与部落，我们找到了家园与朋友，来享受众多的果实。$B$B我们诚心的希望我们所有的盟友都来加入我们的飨宴与庆典。' WHERE `ID` = 14643 AND `text0_0` = 'Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BIn Mulgore and the Horde, we have found both a home and friends to enjoy its many fruits with.$B$BIt is our hope that every one of our allies will be able to join us in feasting and celebration.';
UPDATE `npc_text` SET `text0_0` = '那些牛头人，他们可了解怎么煮东西。你看到他们端出来的食物吗?$B$B我要狂吃到挂掉...等回到墓地再吃更多!' WHERE `ID` = 14644 AND `text0_0` = 'Dem tauren, dey be KNOWIN\' how ta cook. Have ya SEEN all de food dey be servin\'?$B$BI\'m gonna eat \'til I die... an\' den come back from de grave ta be eatin\' some more!';
UPDATE `npc_text` SET `text0_0` = '$N？$G先生:女士;，你不是猎人，你是个$c。' WHERE `ID` = 14796 AND `text0_0` = '$N? $G Sir : Ma\'am;, you\'re not a hunter, you\'re a $c.';
