UPDATE `npc_text` SET `text0_0` = '总共有两个:贸易区的贸易大厅，还有位在矮人区的暴风城拍卖场。' WHERE `ID` = 16601 AND `text0_0` = 'There are two: The Trader\'s Hall in the Trade District, and the Stormwind Auction House in the Dwarven District.';
