UPDATE `npc_text` SET `text0_0` = '城里有两家银行:贸易区的暴风城会计室，还有位在矮人区的暴风城皇家银行。' WHERE `ID` = 16603 AND `text0_0` = 'There are two banks in the city: The Stormwind Counting House in the Trade District, and the Royal Bank of Stormwind in the Dwarven District.';
