UPDATE `npc_text` SET `text0_0` = '我要如何在此来生中协助你?' WHERE `ID` = 16772 AND `text0_0` = 'How may I assist you in the afterlife?';
UPDATE `npc_text` SET `text0_0` = '抱歉，$c。$B$B我想你应该没有足以理解传送魔法之本质的心智能力。' WHERE `ID` = 16790 AND `text0_0` = 'Sorry, $c.$B$BI ain\'t believin\' ya got de right mind for graspin\' de nature of portal magic.';
UPDATE `npc_text` SET `text0_0` = '拍卖场和银行在谷地中间那个高大建筑的最上面，老兄。$B$B去找兹吉和玛卡於。' WHERE `ID` = 16792 AND `text0_0` = 'De auction house and bank be at de top of de tall building in de middle of de valley, mon.$B$BLook for Ziji and Makavu.';
UPDATE `npc_text` SET `text0_0` = '老兄，希贾姆毕就是你要找的人。$B$B她在谷地中间那栋高楼里面。' WHERE `ID` = 16793 AND `text0_0` = 'You be wantin\' Sijambi, mon.$B$BShe be in de tall building in de middle of de valley.';
UPDATE `npc_text` SET `text0_0` = '就在这座谷地的旅店外面，老兄。$B$B中间最高的那一栋楼。' WHERE `ID` = 16794 AND `text0_0` = 'Right outside de valley\'s inn, mon.$B$BIt be de tall building in de middle.';
UPDATE `npc_text` SET `text0_0` = '你是要找哪一个?' WHERE `ID` = 16795 AND `text0_0` = 'Which ya be lookin\' for?';
UPDATE `npc_text` SET `text0_0` = '你该去找沙沙比，老兄。$B$B她通常在渔夫老昂贝托旁边的树下睡觉，像一只大老虎。' WHERE `ID` = 16798 AND `text0_0` = 'You be lookin\' for Sesebi, mon.$B$BShe most often be sleepin\' under de tree by old Umbehto, de fisherman, lookin\' like a big ol\' tiger.';
UPDATE `npc_text` SET `text0_0` = '老兄，卡札里和赞迦正在精神谷东南边尽头的一座小岛上训练猎头者。' WHERE `ID` = 16799 AND `text0_0` = 'Kuzari and Zanga are trainin\' headhunters on one of de small islets towards de southeast end of de valley, mon.';
UPDATE `npc_text` SET `text0_0` = '他们在谷的东南边那栋很高的建筑物顶楼。' WHERE `ID` = 16800 AND `text0_0` = 'Dey be on top of de tall building in de southeast end of de valley.';
UPDATE `npc_text` SET `text0_0` = '暗影行者祖鲁可以帮你。$B$B你可以在东南边那栋较高的房子的最底层找到他。' WHERE `ID` = 16803 AND `text0_0` = 'Shadow-Walker Zuru can help ya.$B$BYou\'ll find him on de lowest floor of de taller building in de southeast.';
UPDATE `npc_text` SET `text0_0` = '暗夜潜猎者库南吉就是你想要找的人。$B$B他就在精神谷中央那栋房子的北边。' WHERE `ID` = 16804 AND `text0_0` = 'Ku\'nanji, de Night-Stalker, is who yer lookin\' for.$B$BHe be just north of de valley\'s central building.';
UPDATE `npc_text` SET `text0_0` = '巫医乌姆布每天都会在精神谷里四处行走，照顾此地的人和元素精魂。$B$B到中央那座建筑的附近去找他。' WHERE `ID` = 16805 AND `text0_0` = 'Witch Doctor Umbu spends his time walkin\' about de valley, tendin\' to de people and elemental spirits alike.$B$BLook for him around de central building.';
UPDATE `npc_text` SET `text0_0` = '你一定疯了，老兄，玩弄坏的魔法。但是我不阻止你。$B$B乌恩贾瑞·魔舌在东南边，经过暗影牧师神庙的那栋高房子里。' WHERE `ID` = 16806 AND `text0_0` = 'You be crazy, mon, meddlin\' with dat bad mojo. But I ain\'t one ta stop ya.$B$BUnjari Feltongue is in de taller building in de southeast, past de shadow priest\'s shrine.';
UPDATE `npc_text` SET `text0_0` = '札姆沙是奥格玛最棒的厨师，老兄。$B$B你可以在精神谷中央建筑的南边找到她。如果你刚好肚子饿的话，巴塔姆希有在卖札姆沙煮的食物。' WHERE `ID` = 16807 AND `text0_0` = 'Zamja be de best cook in Orgrimmar, mon.$B$BYou can find her just south of de valley\'s central building. Batamsi sells de food Zamja makes, too, if ya just be hungry.';
UPDATE `npc_text` SET `text0_0` = '加迪和希尔拉亚工作的地方就在精神谷中央建筑的北边。$B$B你需要什么他们都可以帮你，老兄。' WHERE `ID` = 16808 AND `text0_0` = 'Jandi and Zeal\'aya work from a hut just north of de valley\'s central building.$B$BDey can help ya wit\' whatever ya need, mon.';
UPDATE `npc_text` SET `text0_0` = '胡鸠和克森图有你要的东西。$B$B他们就在精神谷中央建筑里面，老兄。' WHERE `ID` = 16811 AND `text0_0` = 'Huju and Xen\'to can take care of ya.$B$BFind dem in de valley\'s central building, mon.';
UPDATE `npc_text` SET `text0_0` = '克萨迪斯跟他的蛇就在精神谷中间那栋房子里面爬来爬去，老兄。' WHERE `ID` = 16813 AND `text0_0` = 'Xan\'tish and his snakes are slitherin\' around de valley\'s central building, mon.';
UPDATE `npc_text` SET `text0_0` = '这是艾泽拉斯艰难的时期，$n。' WHERE `ID` = 16829 AND `text0_0` = 'These are grave times for Azeroth, $n.';
UPDATE `npc_text` SET `text0_0` = '我无法保证你能够不受干扰地休息，$c。这些兽人不知道何时才会离开。' WHERE `ID` = 16851 AND `text0_0` = 'I cannot promise that your rest will be peaceful, $c.  These orcs do not know when to quit.';
UPDATE `npc_text` SET `text0_0` = '这里「永远」欢迎你和你的钱。' WHERE `ID` = 16870 AND `text0_0` = 'You and your coin are -always- welcome here.';
UPDATE `npc_text` SET `text0_0` = '它被卡住了，而且我也没有蒸汽动力了。这种地形简直要人命啊!$B$B你可以帮我们脱困吗?' WHERE `ID` = 16872 AND `text0_0` = 'She\'s hung up in the debris and I\'ve lost steam pressure. This terrain is murder!$B$BCan you get us out of this?';
UPDATE `npc_text` SET `text0_0` = '恕我直言，但是你恐怕连只科多兽的侧面都射不中。$B$B别浪费彼此的时间，去找个适合你的训练师吧。' WHERE `ID` = 16878 AND `text0_0` = 'No offense, but you don\'t look like you could shoot the broad side of a pack kodo.$B$BHow about we stop wastin\' each other\'s time and you go find the right trainer.';
UPDATE `npc_text` SET `text0_0` = '呦，要来射几箭吗?' WHERE `ID` = 16879 AND `text0_0` = 'Yo. Up for a little target practice?';
UPDATE `npc_text` SET `text0_0` = '嗨，$n。你是来上课的吗?我可不是整天闲闲没事...' WHERE `ID` = 16880 AND `text0_0` = 'Hey there, $N. Here for a lesson? I ain\'t got all day...';
UPDATE `npc_text` SET `text0_0` = '我大老远就听到你走过来的声音了，老兄。看来你还需要更进一步的训练?' WHERE `ID` = 16883 AND `text0_0` = 'I heard ya comin\' a league away, mon. Maybe ya need some more trainin\'?';
UPDATE `npc_text` SET `text0_0` = '什么?你以为我是个$c?$B$B请你走开好吗?' WHERE `ID` = 16884 AND `text0_0` = 'What?  I look like a $c to you?$B$BGet outta here, will ya?';
UPDATE `npc_text` SET `text0_0` = '你需要什么吗?$B$B可惜，我没有东西可以教你，$c。' WHERE `ID` = 16886 AND `text0_0` = 'You need somethin\'?$B$BToo bad. I got nothin\' for ya, $c.';
UPDATE `npc_text` SET `text0_0` = '「好玩又好赚的元素操控法」。$B$B重点就是这样，我说的没错吧?让我们开始吧。' WHERE `ID` = 16887 AND `text0_0` = '"Controlling the Elements for Fun and Profit."$B$BThat\'s what it\'s all about, am I right?  Let\'s get ta work.';
UPDATE `npc_text` SET `text0_0` = '听着，你连想都不会想知道我可以教你的是什么东西。$B$B说真的，那会害你的脑袋融化掉。到别地方去找点简单的题材吧。' WHERE `ID` = 16888 AND `text0_0` = 'Look. You don\'t even WANNA know the sorta stuff I could teach ya.$B$BSeriously. It\'d melt yer brain. Go play nice somewhere else.';
UPDATE `npc_text` SET `text0_0` = '你一定会超爱魔化能量的:便宜，可一用再用，而且肯定能炸掉东西。$B$B当然啦，你得冒着永远失去自我意志给超越时空之难以想像之恐惧的後果，但是嘿嘿，有得必有失嘛!$B$B好啦，你来找我是要干嘛呢?' WHERE `ID` = 16889 AND `text0_0` = 'You gotta love fel energy: Cheap, renewable, and guaranteed to blow things up.$B$BSure, you risk losin\' your eternal will to Unimaginable Horrors from Beyond Time and Space, but hey, risk versus reward!$B$BNow, what did you wanna see me about, hmmm?';
UPDATE `npc_text` SET `text0_0` = '若是你要找位秘法重铸师，在法师区外头的附魔商店里就有一位精灵贵族法师。' WHERE `ID` = 16984 AND `text0_0` = 'If you\'re looking for an Arcane Reforger, there is a highborne mage inside the enchanting shop just outside the Mage District.';
UPDATE `npc_text` SET `text0_0` = '可怜的人，你一定累坏了。$B$B如果你需要，我们这有食物和水，也可在这休息，这是安全的。' WHERE `ID` = 16988 AND `text0_0` = 'Poor dear, you must be exhausted.$B$BThere\'s food and drink, if you like, and it\'s safe to rest here.';
UPDATE `npc_text` SET `text0_0` = '想吃点东西吗，$c?$B$B还是只想歇歇你一身的累骨头?' WHERE `ID` = 16989 AND `text0_0` = 'Looking for something to eat, $c?$B$BOr just a place to rest your weary bones for a while?';
UPDATE `npc_text` SET `text0_0` = '呦。$B$B你是来寄放宠物的，还是来寻找失踪的夥伴?' WHERE `ID` = 16996 AND `text0_0` = 'Yo.$B$BYou here to stable your pets, or lookin\' for a lost companion?';
UPDATE `npc_text` SET `text0_0` = '呦。$B$B你是要寻找失踪的夥伴?' WHERE `ID` = 16997 AND `text0_0` = 'Yo.$B$BYou lookin\' for a lost companion?';
UPDATE `npc_text` SET `text0_0` = '好……渴……' WHERE `ID` = 17046 AND `text0_0` = 'So... thirsty...';
UPDATE `npc_text` SET `text0_0` = '这个矮人死状十分凄惨，暮光之锤的人必定以凌虐他为乐。' WHERE `ID` = 17051 AND `text0_0` = 'This dwarf\'s body is severely battered. The Twilight\'s Hammer must take pleasure in their killing.';
UPDATE `npc_text` SET `text0_0` = '你的死期到了。' WHERE `ID` = 17057 AND `text0_0` = 'Your time is coming to an end.';
UPDATE `npc_text` SET `text0_0` = '在燃刃氏族落败之後，我们这些大剑师便立誓要解放自己与同胞们远离恶魔的控制。$B$B这件事情虽然已经办到了，但是我个人的荣誉依然存有污点。$B$B我将为部落而战，并且将这观念灌输给其他的战士们，直到我在战场上光荣战死。这就是我唯一的赎罪之道。$B$B那么，你准备好接受训练了吗?' WHERE `ID` = 17086 AND `text0_0` = 'After the fall of the Burning Blade Clan, we blademasters swore to free ourselves and our people from demonic control.$B$BThis may be done, but my honor remains unsatisfied.$B$BI shall fight for the Horde - and train other warriors to do so - until I die gloriously in battle. This is the only path I may tread.$B$BSo. Are you ready to train?';
UPDATE `npc_text` SET `text0_0` = '看守银行和部落的财宝远比躲在铁笼里收发钱币和物品来得有意义多了。$B$B我一点也不想跟那些成天拿笔算钱记帐的哥布林交换工作。' WHERE `ID` = 17087 AND `text0_0` = 'Guarding the bank and treasures of the Horde is far more satisfying than dispensing coins and trade goods from inside a cage of iron.$B$BI would not exchange places with one of those quill-pushing goblins for a moment.';
UPDATE `npc_text` SET `text0_0` = '嘿，你好!' WHERE `ID` = 17143 AND `text0_0` = 'Hey there, good lookin\'.';
UPDATE `npc_text` SET `text0_0` = '我们对秘法的秘密已忽视了太久。$B$B你也是来学习的吗?' WHERE `ID` = 17175 AND `text0_0` = 'For too long we have ignored the secrets of the Arcane.$B$BAre you here to learn, as well?';
UPDATE `npc_text` SET `text0_0` = '你也是一位研习秘法的学徒?$B$B如果你想学的话，我可以教你如何开启传送门的法术。' WHERE `ID` = 17181 AND `text0_0` = 'You too are a student of the arcane, yes?$B$BI can teach you about portal magic, if you wish to learn.';
UPDATE `npc_text` SET `text0_0` = '我恐怕帮不了你，$r，但是我相信凯琳·钢翼应该可以。' WHERE `ID` = 17187 AND `text0_0` = 'I\'m afraid I cannot help you, $r, but I am sure Khaelyn Steelwing can.';
UPDATE `npc_text` SET `text0_0` = '我恐怕帮不了你，$r，但是我相信乔吉亚应该可以。' WHERE `ID` = 17188 AND `text0_0` = 'I\'m afraid I cannot assist you, $r, but I am certain Georgia can.';
UPDATE `npc_text` SET `text0_0` = '穿过这道传送门，托巴拉德在等着你。' WHERE `ID` = 17194 AND `text0_0` = 'Through this portal, Tol Barad awaits.';
UPDATE `npc_text` SET `text0_0` = '若是你要找位秘法重铸师，在法师区外头的附魔商店里就有一位精灵贵族法师。' WHERE `ID` = 17204 AND `text0_0` = 'If you\'re looking for an Arcane Reforger, there is a blood elf mage inside the Drag\'s enchanting shop, Godan\'s Runeworks.';
UPDATE `npc_text` SET `text0_0` = '<穆兰狮鹫骑士伫立不动，目光凝视前方，丝毫不理会你。>' WHERE `ID` = 17208 AND `text0_0` = '<The Mullan Gryphon Rider stays still, eyes locked forward, not acknowledging your presence.>';
UPDATE `npc_text` SET `text0_0` = '杜格拉斯是派你过来讨打的吗?' WHERE `ID` = 17212 AND `text0_0` = 'Duglas send you over to get roughed up?';
UPDATE `npc_text` SET `text0_0` = '你想找的人是亚当·霍沙克。他在法师区南侧内环的地方有个办事处。$B$B只要他没有出去探险，他应该都会待在那里。' WHERE `ID` = 17216 AND `text0_0` = 'You\'ll want to find Adam Hossack. He\'s got an office in the southern Mage Quarter along the inner ring.$B$BIf he\'s not out exploring, he\'ll likely be there.';
UPDATE `npc_text` SET `text0_0` = '你要找的屍体就叫迪罗·虫林。他通常位在本镇的南边。' WHERE `ID` = 17226 AND `text0_0` = 'Dedlow Wormwood\'s the corpse you want. He\'s usually around the south end of town.';
UPDATE `npc_text` SET `text0_0` = '这个兽人受了重伤。' WHERE `ID` = 17228 AND `text0_0` = 'This orc is severely injured.';
UPDATE `npc_text` SET `text0_0` = '你是谁?' WHERE `ID` = 17235 AND `text0_0` = 'Who are you?';
UPDATE `npc_text` SET `text0_0` = '你是要来接受训练的吗，猎人?' WHERE `ID` = 17266 AND `text0_0` = 'Have you come for training, hunter?';
UPDATE `npc_text` SET `text0_0` = '铁裤教授人应该在探险者大厅里。' WHERE `ID` = 17299 AND `text0_0` = 'The good Doktor Professor Ironpants may be found in the Hall of Explorers.';
UPDATE `npc_text` SET `text0_0` = '你在吉布的草须魔法用品店里就能找到一位秘法重铸师，在大锻炉的狮鹫兽管理员那边。$B$B他也是个消失很久的精灵贵族，但是他可以帮你搞定。' WHERE `ID` = 17300 AND `text0_0` = 'Ye\'ll find an Arcane Reforger in Gimble\'s shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge.$B$BHe\'s one o\' them long-lost Highborne elves, but he\'ll do ye right.';
UPDATE `npc_text` SET `text0_0` = '在力量谷的中央要塞里有一位血精灵，他是银月城派来的，叫做贝洛克。他就是你要找的人。' WHERE `ID` = 17302 AND `text0_0` = 'There is a blood elf in the Valley of Strength\'s central fortress, part of a delegation from Silvermoon: Belloc. He is who you want.';
UPDATE `npc_text` SET `text0_0` = '法师们应该是在暗影裂口里。那边有两个入口:一个在力量谷和智慧谷的中间，另一个是在暗巷区。' WHERE `ID` = 17303 AND `text0_0` = 'The mages may be found in Cleft of Shadow.  There are two entrances: One between the valleys of Strength and Wisdom, and the other in The Drag.';
UPDATE `npc_text` SET `text0_0` = '有一位学者叫做『疲倦不堪』的汉孟德可以帮你的忙。你可以在月神殿里找到他，他经常在那边和归来的精灵贵族讲话。' WHERE `ID` = 17318 AND `text0_0` = 'There is a scholar, Arunel, who can assist you.  You will find him in the Temple of the Moon, often conversing with one of the returned Highborne.';
UPDATE `npc_text` SET `text0_0` = '我认识你吗?不认识?欢迎加入暮光之锤。' WHERE `ID` = 17319 AND `text0_0` = 'Do I know you? No? Welcome to the Twilight\'s Hammer.';
UPDATE `npc_text` SET `text0_0` = '欧托·灰皮大多都在长者高地的长者大厅里。去那边找他，他会帮你。' WHERE `ID` = 17323 AND `text0_0` = 'Otoh Greyhide spends much of time in the Hall of Elders on the Elder Rise.  Seek him out there, and he will help you.';
UPDATE `npc_text` SET `text0_0` = '你可以在猎人高地上找到日行者的小屋。' WHERE `ID` = 17324 AND `text0_0` = 'You will find the Sunwalker\'s Lodge on Hunter\'s Rise.';
UPDATE `npc_text` SET `text0_0` = '本城的秘法重铸师是女巫师费菈，她可以帮得了你。她通常是在阳光庭院里跟她的学徒希丹娜在讨论事情。' WHERE `ID` = 17327 AND `text0_0` = 'The city\'s Arcane Reforger, Enchantress Fira, will be able to help you.  She is most often found with Sedana and her enchanter\'s apprentices, off the Court of the Sun.';
UPDATE `npc_text` SET `text0_0` = '『追寻者』波度罗经常会出现在阴郁城的商店街。是我的话我就会去那里找他。' WHERE `ID` = 17334 AND `text0_0` = 'Boduro the Seeker can often be found in the merchant\'s bazaar within the Lower City. I would look for him there.';
UPDATE `npc_text` SET `text0_0` = '高等精灵博学者法师达莉诺丝是本城最学识渊博的考古学家...而且也是最善於交际的人。$B$B她通常都待在戏法旅舍，就在市中心的北方，在那边享受气氛，还有跟店主和投资人讨论她惊奇的冒险故事。' WHERE `ID` = 17336 AND `text0_0` = 'The high elf mage and scholar Dariness is the city\'s most learned archaeologist... and the most sociable.$B$BShe can often be found in the Legerdemain Lounge, just north of the city\'s center, enjoying the atmosphere or discussing her wild adventures with the proprieters and patrons both.';
UPDATE `npc_text` SET `text0_0` = '你在找训练？不行。我不是你要找的人。' WHERE `ID` = 17345 AND `text0_0` = 'You lookin\' for trainin\'? No can do. I ain\'t your guy.';
UPDATE `npc_text` SET `text0_0` = '大块头，在找人训练吗?' WHERE `ID` = 17346 AND `text0_0` = 'You lookin\' to train up, bruiser?';
UPDATE `npc_text` SET `text0_0` = '现在我们既然占领了这座可悲的岛屿，我们需要做些工作来整顿一番。你能帮我们吗，$n?' WHERE `ID` = 17419 AND `text0_0` = 'Now that we have captured this wretched isle, we need to do some work to get it into shape.  Can you help us out $n?';
UPDATE `npc_text` SET `text0_0` = '我并不喜欢那个大家都在谈论的D区。但是在我们开始使用它之前，我们的确有些工作得进行。' WHERE `ID` = 17420 AND `text0_0` = 'I am not a fan of that d-block place everyone keeps talking about it.  We do have some tasks that must be completed before we can use it though.';
UPDATE `npc_text` SET `text0_0` = '我猜你现在已经听说过那个洞了，$r。如果还没有，你很快就会听到一大堆关於它的事情。' WHERE `ID` = 17421 AND `text0_0` = 'I assume you have heard of the hole by now, $r.  If not, you are going to know a whole lot about it soon.';
UPDATE `npc_text` SET `text0_0` = '欢迎来到托巴拉德，$c。我们在浪费时间，赶快开始工作吧。' WHERE `ID` = 17422 AND `text0_0` = 'Welcome to Tol Barad, $c.  Time\'s a wastin\' so let\'s get to work.';
UPDATE `npc_text` SET `text0_0` = '看来教徒们已经注意到德鲁伊了!$B$B你可以透过传送门的漩涡看见野性之心营地!穿过它肯定能把你带回营地。$B$B等你在这里的事情办妥，这会是快速离开的好方法。' WHERE `ID` = 17451 AND `text0_0` = 'It looks like the cultists had their eye on the druids!$B$BYou can see Wildheart Point through the swirling portal. Stepping through it will take you on a one-way trip back to the camp.$B$BOnce your business here is finished, this would be a good way to make a quick exit.';
UPDATE `npc_text` SET `text0_0` = '你可以在铸造厂附近的远行者广场找到『壁垒』艾尔苏达和其他战士训练师们。' WHERE `ID` = 17459 AND `text0_0` = 'Alsudar the Bastion and the other warrior trainers may be found overlooking Farstriders\' Square, from near the foundry.';
UPDATE `npc_text` SET `text0_0` = '这附近还有很多事情得处理，$r。你准备好来帮忙了吗?' WHERE `ID` = 17461 AND `text0_0` = 'Lot\'s to be done around here, $r.  Are you ready to help?';
UPDATE `npc_text` SET `text0_0` = '欢迎来到巴拉丁营地。我知道这里现在看起来不怎么样，但只要稍微努力一番，我们就能把这里整顿得很像样。' WHERE `ID` = 17462 AND `text0_0` = 'Welcome to baradin base camp.  I know it does not look like much now, but with a little hard work we can whip this place into shape.';
UPDATE `npc_text` SET `text0_0` = '看起来这里有做不完的事。每天凌晨三点都会有新的命令，真的很奇怪。' WHERE `ID` = 17463 AND `text0_0` = 'Seems like we never run out of things to do around here.  New orders arrive every day at 3am, it\'s really strange.';
UPDATE `npc_text` SET `text0_0` = '我很希望能成交，夥伴，我真的这么希望。但是你必须得先和污水企业联合达到崇拜的声望才行。' WHERE `ID` = 17494 AND `text0_0` = 'I wish I could make you a deal, partner - I really do - but you\'ll need to be exalted with the Bilgewater Cartel, first.';
UPDATE `npc_text` SET `text0_0` = '嗨!我是考尔·沃瑟顿，污水机动车。$B$B别客气，到处看看吧。选出你真正想要的机动车!$B$B一辆骑起来很爽的机动车...一辆危险而在生死边缘游转的机动车...一辆能让你感到骄傲的机动车!$B$B等你决定了，跟我说一声，我们可以马上成交。' WHERE `ID` = 17495 AND `text0_0` = 'Yo! I\'m Kall Worthaton, Bilgewater Trikes.$B$BGo ahead, look over the lot. Pick out the trike that you REALLY want!$B$BA trike that\'s a blast to ride... a trike that\'s dangerous and death-defying... a trike you can be PROUD of!$B$BYou let me know when you see it, and we\'ll make a deal.';
UPDATE `npc_text` SET `text0_0` = '他们在谷的东南边那栋很高的建筑物顶楼。' WHERE `ID` = 17498 AND `text0_0` = 'Dey be on top of de tall building in de southeast end of de valley.';
UPDATE `npc_text` SET `text0_0` = '欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B玛法里恩在照看着我们，所以我们永远是平衡的守卫者。别忘了这一点。' WHERE `ID` = 17615 AND `text0_0` = 'Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, with Malfurion watching over us.  Never forget this.';
UPDATE `npc_text` SET `text0_0` = '我们的主人玛法里恩从梦境中归来了，$c。他是替我们指引道路的光明灯塔，而我们必须尽一切所能来维持这盏光明。' WHERE `ID` = 17616 AND `text0_0` = 'Our master Malfurion has returned from the Dreaming, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light.';
UPDATE `npc_text` SET `text0_0` = '我无法帮助你，$c。' WHERE `ID` = 17659 AND `text0_0` = 'I cannot help you, $c.';
UPDATE `npc_text` SET `text0_0` = '我很抱歉，$c，但是精灵贵族们的秘法奥秘对你来说永远会是个秘密。' WHERE `ID` = 17745 AND `text0_0` = 'My apologies, $c, but the arcane secrets of the Highborne will forever remain secrets to you.';
UPDATE `npc_text` SET `text0_0` = '现代的魔法跟千年前根本无法相比。即使如此，我们精灵贵族仍然知道许多秘法的奥妙。你准备好进行学习了吗?' WHERE `ID` = 17747 AND `text0_0` = 'The magic of today pales in comparison to that of millennia past. Still, we Highborne know much of the arcane. Are you ready to learn?';
UPDATE `npc_text` SET `text0_0` = '你可以在雷酒酿酒厂找到蛮锤部族的哈尔宾·霜锤。他可以教导你萨满之道。' WHERE `ID` = 17748 AND `text0_0` = 'Halbin Frosthammer, from the Wildhammer clan, can be found in Thunderbrew Distillery.  He can help teach ya the ways of the shaman.';
UPDATE `npc_text` SET `text0_0` = '在勇者大厅外面找找双足翼龙之尾酒馆。' WHERE `ID` = 17753 AND `text0_0` = 'Look for The Wyvern\'s Tail, just outside the Hall of the Brave.';
UPDATE `npc_text` SET `text0_0` = '那得穿过前往暗巷区门口的桥。听到哥布林在大喊就是了。' WHERE `ID` = 17754 AND `text0_0` = 'It\'s across the bridge from the gate to The Drag. Listen for the sound of shouting goblins.';
UPDATE `npc_text` SET `text0_0` = '荣誉谷的银行就在暗巷区的入口。' WHERE `ID` = 17758 AND `text0_0` = 'The Valley of Honor\'s bank is just before the gate to The Drag.';
UPDATE `npc_text` SET `text0_0` = '想要找到鲁瑟兰码头，你得先去达纳苏斯，通过传送门进入鲁瑟兰村。' WHERE `ID` = 17759 AND `text0_0` = 'To reach the Rut\'theran Ferry, you will need to travel to Darnassus and take the portal to Rut\'theran Village at the base of Teldrassil.';
UPDATE `npc_text` SET `text0_0` = '正有位精灵贵族大法师来到城内拜访附魔训练师。你可以在那里重铸你的物品。' WHERE `ID` = 17770 AND `text0_0` = 'There is a Highborne archmage visiting the city\'s Enchanting trainer. You can have your items reforged there.';
UPDATE `npc_text` SET `text0_0` = '哪一个?' WHERE `ID` = 17774 AND `text0_0` = 'Which one?';
UPDATE `npc_text` SET `text0_0` = '选择目的地。' WHERE `ID` = 17791 AND `text0_0` = 'Choose a destination.';
UPDATE `npc_text` SET `text0_0` = '我会在你的地图上标示地点。' WHERE `ID` = 17793 AND `text0_0` = 'I will mark the location upon your map.';
UPDATE `npc_text` SET `text0_0` = '幸会，$c。我给你的建议是：周游世界时务必警惕魔法，因为它会灼伤未经训练之人。' WHERE `ID` = 17800 AND `text0_0` = 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.';
UPDATE `npc_text` SET `text0_0` = '这个传送装置看起来最近刚被用来把一些货物送到矿坑的更深处。' WHERE `ID` = 17824 AND `text0_0` = 'This teleportation device appears to have been used recently to teleport various goods deeper into the mine.';
UPDATE `npc_text` SET `text0_0` = '这里欢迎任何人前来对火焰表示敬意，$c。虽然有很多盏火焰已并非原先那些，而是熄灭之後重新点燃的。$b$b在陶土议会，我们只是单纯对火焰表示敬意，没有其他任何轻薄举动。$b$b在这，我们遵照传统规定来荣耀火焰。你愿意加入我们吗，$n?' WHERE `ID` = 17840 AND `text0_0` = 'Though many flames are fought over, extinguished and re-lit, all are welcome to show honor to the flame, $c.$b$bHere among the Earthen Ring, we simply honor the flame, rather than engage in other frivolities.$b$bHere, we will honor the flame as tradition dictates.  Will you join with us in honoring the flame, $n?';
UPDATE `npc_text` SET `text0_0` = '虽然我很想念吉尔尼斯，但还有很多远古遗蹟等着我去探索!' WHERE `ID` = 17859 AND `text0_0` = 'While I miss Gilneas greatly, there\'s ancient ruins to explore!';
UPDATE `npc_text` SET `text0_0` = '我们在托巴拉德岛上的巴拉丁堡的弟兄十分繁忙，而且在你需要的时候，他们总是没空理你。我日以继夜地守在这里，就是要帮忙处理他们可能会交付给你的任务。' WHERE `ID` = 17866 AND `text0_0` = 'Our brothers at Baradin Hold on Tol Barad are very busy and not always available when you need them.  I have been stationed here around the clock to help you with tasks they might have given you.';
UPDATE `npc_text` SET `text0_0` = '你在寻求力量，是吗?但是你会愿意像我一样踏上那条受诅咒的道路吗?' WHERE `ID` = 17891 AND `text0_0` = 'You seek power, yes? But will you walk the cursed path I do for it?';
UPDATE `npc_text` SET `text0_0` = '在我面前是一片黑暗，充满了诅咒，$c。你不会想跟我一起走下去的。' WHERE `ID` = 17892 AND `text0_0` = 'My path is a dark and cursed one, $c. You do not wish to walk with me.';
UPDATE `npc_text` SET `text0_0` = '欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。' WHERE `ID` = 17904 AND `text0_0` = 'Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.';
UPDATE `npc_text` SET `text0_0` = '如果你在寻求传统的训练方式，我帮不上忙。' WHERE `ID` = 17905 AND `text0_0` = 'If you seek training in the Old Ways, I cannot help you.';
UPDATE `npc_text` SET `text0_0` = '在城门外有名叫做达锐斯的狼人德鲁伊，他应该能帮上你的忙。$B$B去找一个全身覆满皮毛的大家伙，你一眼就能看出是他。' WHERE `ID` = 17906 AND `text0_0` = 'There\'s a worgen druid by the name of Dareth just outside the city gates; he might be able to help you.$B$BBig beast of a fellow, covered in white leather and furs. You can\'t miss him.';
UPDATE `npc_text` SET `text0_0` = '你要找深山矿工与珠宝设计协会?就在大锻炉的北面。' WHERE `ID` = 17961 AND `text0_0` = 'Ye want Deepmountain Mining and Jewelcrafting, over on the northern side of The Great Forge.';
UPDATE `npc_text` SET `text0_0` = '铁匠和助手们在战士区的护甲商及武器商附近。' WHERE `ID` = 17967 AND `text0_0` = 'A blacksmith and his assistant can be found working in the Warrior\'s Terrace, near the armor and weapon vendors there.';
UPDATE `npc_text` SET `text0_0` = '到弓箭场找杰森·法兰。' WHERE `ID` = 18087 AND `text0_0` = 'Look for Jensen Farran near the archery range.';
UPDATE `npc_text` SET `text0_0` = '你会在普劳德摩尔女士的塔上找到在踱步的贺瑞斯·欧德尔。' WHERE `ID` = 18088 AND `text0_0` = 'You\'ll find Horace Alder pacing about above the ground level of Lady Proudmoore\'s tower.';
UPDATE `npc_text` SET `text0_0` = '在兵营外找正在训练假人处监督训练的卡尔曼修士。' WHERE `ID` = 18089 AND `text0_0` = 'Look for Brother Karman overseeing training at the combat dummies outside the barracks.';
UPDATE `npc_text` SET `text0_0` = '我不确定。试着问问看在码头的卡莉雅·哈斯丁。我听说她在军情七处有认识的人。' WHERE `ID` = 18091 AND `text0_0` = 'I\'m not certain. Try asking Calia Hastings, by the docks. I\'m told she has connections to SI:7.';
UPDATE `npc_text` SET `text0_0` = '向兵营二楼的伊文凯恩队长回报。他会安排你要进行的训练。' WHERE `ID` = 18094 AND `text0_0` = 'Report to Captain Evencane on the second level of the barracks. He can see to your training.';
UPDATE `npc_text` SET `text0_0` = '链金师纳瑞特和布兰特·加斯布鲁姆在这里的一间小店铺教导链金和草药学。他们应该可以帮到你。' WHERE `ID` = 18095 AND `text0_0` = 'Alchemist Narett and Brant Jasperbloom teach Alchemy and Herbalism out of a small shop here; they\'ll be able to help you.';
UPDATE `npc_text` SET `text0_0` = '去铁匠铺那里找玛蕾·霍斯顿。' WHERE `ID` = 18097 AND `text0_0` = 'Ask for Marie Holdston at the smithy.';
UPDATE `npc_text` SET `text0_0` = '克瑞格·诺瓦德在旅店的厨房做事。他可以帮你。' WHERE `ID` = 18098 AND `text0_0` = 'Craig Nollward works the inn\'s kitchen. He\'ll be able to help you.';
UPDATE `npc_text` SET `text0_0` = '在法师塔上的丽莎亚·史贝尔维克是珍娜女士手下附魔师的老大。' WHERE `ID` = 18099 AND `text0_0` = 'Lissah Spellwick, at the top of mage tower, is the mistress of Lady Jaina\'s enchanters.';
UPDATE `npc_text` SET `text0_0` = '去铁匠铺那里找卡兹·双链。' WHERE `ID` = 18100 AND `text0_0` = 'Look for Caz Twosprocket at the smithy.';
UPDATE `npc_text` SET `text0_0` = '古斯塔夫·范沃森医生在兵营的一楼工作。' WHERE `ID` = 18101 AND `text0_0` = 'Doctor Gustaf VanHowzen works on the ground level of the barracks.';
UPDATE `npc_text` SET `text0_0` = '在码头那里的麦可·克罗威可以教你捕鱼和切鱼的技术。' WHERE `ID` = 18102 AND `text0_0` = 'Michael Crowe, down by the docks, can teach you anything you need to know about catching and gutting fish.';
UPDATE `npc_text` SET `text0_0` = '到普劳德摩尔女士的塔顶找希优顿·曼那斯。' WHERE `ID` = 18103 AND `text0_0` = 'Look for Theoden Manners at the top of Lady Proudmoore\'s tower.';
UPDATE `npc_text` SET `text0_0` = '到瑟拉摩的旅店找谭威尔兄弟。他们当中会有人能帮你。' WHERE `ID` = 18105 AND `text0_0` = 'Seek out the Tanwell brothers in Theramore\'s inn. One of them will be able to help you.';
UPDATE `npc_text` SET `text0_0` = '你应该去找山夏·马克凡斯，在塞拉摩尔的马厩外面。' WHERE `ID` = 18107 AND `text0_0` = 'You\'ll want to find Sansha MacVince, just outside Theramore\'s stables.';
UPDATE `npc_text` SET `text0_0` = '提摩西·沃森特在塞拉摩比较大间的建筑物之一工作。你可以在二楼找到他，他帮得到你。' WHERE `ID` = 18108 AND `text0_0` = 'Timothy Worthington works out of the second floor of one of Theramore\'s larger buildings. He\'ll do you right.';
UPDATE `npc_text` SET `text0_0` = '我现在没空说教，$c。去别的地方寻找你的知识。' WHERE `ID` = 18162 AND `text0_0` = 'I have no time for a sermon now, $c. Seek your knowledge elsewhere.';
UPDATE `npc_text` SET `text0_0` = '圣光给我们足以获得胜利的力量和魔法。' WHERE `ID` = 18163 AND `text0_0` = 'The Light gives us the strength and magic to triumph.';
UPDATE `npc_text` SET `text0_0` = '很抱歉，$c。我以为你是个有骨气的人。你走吧;我们的秘密不告诉不牢靠的人。' WHERE `ID` = 18166 AND `text0_0` = 'I apologize, $c. I mistook you for someone with a spine. Begone; our secrets are not for untrained ears.';
UPDATE `npc_text` SET `text0_0` = '我们没什么好谈的，$c。或许你该去找别人，和你比较志趣相投的人。' WHERE `ID` = 18168 AND `text0_0` = 'We have little to discuss, $c. Perhaps you should seek other, more like-minded individuals.';
UPDATE `npc_text` SET `text0_0` = '你喜欢枪械还是弓箭?' WHERE `ID` = 18169 AND `text0_0` = 'Do you prefer guns or bows?';
UPDATE `npc_text` SET `text0_0` = '我只训练战士而已，$c。你得去别的地方找你的训练师。' WHERE `ID` = 18170 AND `text0_0` = 'I train only warriors, $c. You\'ll have to look elsewhere.';
UPDATE `npc_text` SET `text0_0` = '我们的道路是给那些有钢铁意志和坚定决心的人走的。你看起来并不拥有这些特质，$c。' WHERE `ID` = 18172 AND `text0_0` = 'Ours is a path for those with an iron will and unfaltering resolve. You seem to possess none of these traits, $c.';
UPDATE `npc_text` SET `text0_0` = '$n，想要我怎样帮你进行训练?' WHERE `ID` = 18174 AND `text0_0` = '$N, how may I further your training?';
UPDATE `npc_text` SET `text0_0` = '如果你在寻求训练，我帮不上忙。' WHERE `ID` = 18175 AND `text0_0` = 'If you seek training, I cannot help you.';
UPDATE `npc_text` SET `text0_0` = '看来你做了错误的选择，$c。' WHERE `ID` = 18176 AND `text0_0` = 'It appears you took a wrong turn, $c.';
UPDATE `npc_text` SET `text0_0` = '你来加入战斗的吗，$c?' WHERE `ID` = 18195 AND `text0_0` = 'You come to join the fight, $c?';
UPDATE `npc_text` SET `text0_0` = '暗月马戏团开了!$b$b只要一点费用，我就可以把你传送到筹备区去。$b$b你想要去吗?' WHERE `ID` = 18269 AND `text0_0` = 'The Darkmoon Faire is now open!$b$bFor a small fee, I can teleport you to the fairground staging area.$b$bWould you like to go?';
UPDATE `npc_text` SET `text0_0` = '我们的以太魔科技有着以前的人无法想像的能力，可以修改物品秘法本质。我们能把物品存进一处独立次元...只要少许的费用。详情请洽询我的同事。$B$B或者，你有东西要让我看看吗?' WHERE `ID` = 18280 AND `text0_0` = 'Our ethereal technomancy has the ability to modify an item\'s arcane essence in ways previously unimaginable. We can also house items in a pocket dimension... for a small fee. See my associates for details.$B$BUnless you have something for me to examine?';
UPDATE `npc_text` SET `text0_0` = '嘿，嘿!$B$B我想你一定可以把圈圈丢到慢吞吞的乌龟身上。$b$b怎么样?' WHERE `ID` = 18284 AND `text0_0` = 'Hey, hey!$B$BI\'m sure you can land a ring on a slow-moving turtle.$b$bWhat do you say?';
UPDATE `npc_text` SET `text0_0` = '你先给我一个游戏代币，然後我给你十个圈圈。$b$b把圈圈丢到那边的肚边龟身上... 有看到牠背上的杆子吗?。$b$b就算你丢中的圈圈不够多、没法一次获胜，只要再试一次就好了!你的点数可以沿用到下场游戏。' WHERE `ID` = 18286 AND `text0_0` = 'You give me a game token, and I\'ll give you ten rings. $B$BThrow the rings onto the Dubenko the Darkmoon Turtle over there... see the pole he\'s carrying on his shell?$b$bIf you don\'t land enough rings to win in one go, try again! Your points carry over into your next game.';
UPDATE `npc_text` SET `text0_0` = '要架设马戏团的场地并进行维护，是件很艰难的工作...' WHERE `ID` = 18288 AND `text0_0` = 'Setting up and maintaining the grounds is tough work...';
UPDATE `npc_text` SET `text0_0` = '我们有锤子、有豺狼人。$b$b只要你有代币，就可以用锤子痛扁豺狼人。' WHERE `ID` = 18289 AND `text0_0` = 'We\'ve got hammers, we\'ve got gnolls.$b$bIf you\'ve got a token, you can use the hammer to whack some gnolls.';
UPDATE `npc_text` SET `text0_0` = '在找旧版的蒸汽坦克吗?$b$b我们有新版的让你玩呢。$b$b通常，你会需要花费两个代币才能使用坦克的遥控装置。但是因为你在军事上的贡献，我们给了你只要花一个代币的折扣。$b$b我们暗月马戏团感谢你的服务。' WHERE `ID` = 18290 AND `text0_0` = 'Looking for the old steam tonks?$b$bWell, we\'ve got some new ones for you to enjoy.$b$bNormally, it would cost two tokens to use a tonk remote.  But because of your military service, you get a discounted rate of one token.$b$bWe at the Darkmoon Faire thank you for your service.';
UPDATE `npc_text` SET `text0_0` = '已经没有游戏能让你玩了。' WHERE `ID` = 18317 AND `text0_0` = 'No more games for you.';
UPDATE `npc_text` SET `text0_0` = '我能帮你什么忙吗？' WHERE `ID` = 18321 AND `text0_0` = 'How may I help you?';
UPDATE `npc_text` SET `text0_0` = '我能帮你什么忙吗？' WHERE `ID` = 18322 AND `text0_0` = 'How may I help you?';
UPDATE `npc_text` SET `text0_0` = '你要有暗月游戏代币才能玩。$b$b马戏团的每个代币商人都有卖。$b$b我会帮你标记在你的地图上。' WHERE `ID` = 18348 AND `text0_0` = 'You need Darkmoon Game Tokens to play.$b$bBuy them from any of the faire\'s Game Token vendors.$b$bI\'ll mark one on your map for you.';
UPDATE `npc_text` SET `text0_0` = '首先，你先给我一个游戏代币。然後，我会给你一把锤子。你会看到豺狼人从游戏区的桶子里冒出来。$B$B用锤子打中豺狼人，你就会获得分数。$b$b要特别注意的是，桶子会出现三种目标:普通豺狼人、大豺狼人，还有宝宝。$b$b普通豺狼人能获得一分，大豺狼人算三分。至於宝宝?打中宝宝会害你摔跤晕倒...所以千万不要动手打宝宝!$b$b如果你时间内无法打到够多的豺狼人，只要多花个代币就好了!因为你累积的点数是可以沿用到下一场游戏的。' WHERE `ID` = 18350 AND `text0_0` = 'First, you give me a game token.  Next, I give you a mallet.  Then you\'ll see gnolls pop from the barrels in the play area.$B$BHit the gnolls with your mallet to score points.$b$BHere\'s where it gets tricky.  There are three different targets: regular gnolls, Hogger gnolls, and BABIES.$b$bRegular gnolls grant one point, while Hoggers count for three.  But babies?  Hitting a baby will knock you down and stun you... SO DON\'T HIT THE BABIES!$b$bIf you don\'t whack enough gnolls in one go, just spend another token!  The points you\'ve earned will carry over into your next game.';
UPDATE `npc_text` SET `text0_0` = '首先，你先给我一个游戏代币，然後你就能控制一台蒸汽坦克。$b$b你得在限定的时间内击中战场上的目标，每摧毁一个目标就能赢得一点积分。$b$b但要小心:战场上同时也有着敌方的坦克跟飞艇，被它们击中会使你的坦克受损。$b$b你的分数在结束後会带到下一场游戏中，所以就算被打爆了也不用担心。' WHERE `ID` = 18352 AND `text0_0` = 'First, you give me one game token.  Then you find yourself in control of a steam tonk!$b$bYou have a limited amount of time to blast targets in the battlefield.  Each target you destroy earns you one point.$b$bBut watch out: The battlefield is also home to enemy tonks and zeppelins.  Getting hit by one of their shots damages your tonk.$b$bYour score will carry over from one tonk to the next, so don\'t worry if you explode.';
UPDATE `npc_text` SET `text0_0` = '首先，你得给我一个游戏代币，我就给你一把气弹步枪。$B$B然後，用它射击亮起来的目标。$b$b如果你动作够快，在目标亮起来之後立刻射中它，就能获得额外的分数。$b$b如果你在时间结束前没办法达到指定的分数，或你离开了场地，也不用担心。你的分数会保留到下一场游戏计算。' WHERE `ID` = 18353 AND `text0_0` = 'First, I give you a pellet rifle in exchange for one Darkmoon Game Token.$B$BThen you shoot the targets that light up.$b$bIf you\'re fast enough to hit a target just after it\'s lit up, you get an extra point.$b$bIf you don\'t reach the score limit before your time\'s up, or you move away from the booth, don\'t worry: Your score carries over to the next game.';
UPDATE `npc_text` SET `text0_0` = '您好，$c，欢迎来到暗月马戏团的筹备区。$b$b这里的门会把你带到暗月马戏团的位置。$b$b但若您在前往之前有任何问题，我可以帮忙回答。' WHERE `ID` = 18362 AND `text0_0` = 'Hello and welcome to the Darkmoon Faire Staging Area.$b$bThe portal here will take you to the Darkmoon Faire.$b$bBut if you have any questions before you go, I can answer them.';
UPDATE `npc_text` SET `text0_0` = '暗月马戏团里头有很多令人惊叹的东西。我们有个占卜师，一场演唱会、一场钓鱼比赛跟许多小游戏。$b$b我们一直在持续用新花样来扩张马戏团的规模!$b$b有任何特别的东西是你想知道的吗?' WHERE `ID` = 18363 AND `text0_0` = 'The Darkmoon Faire is filled with all sorts of amazing attractions.  We have a fortune teller, a concert, a fishing contest and a lot of games.$b$bWe are constantly expanding the faire with all manner of new attractions!$b$bAre there any attractions you\'d like more information on?';
UPDATE `npc_text` SET `text0_0` = '小型坦克，就我记忆所及，一直都是马戏团里面很抢手的游戏。$b$b我们有两个竞技场来让坦克进行战斗。$b$b一个竞技场要你在有限时间内摧毁目标，并避免被敌方坦克击破。你只需要一个代币就可以玩了$b$b在另一个竞技场里面，你可以使用自己的坦克或迷你飞艇跟朋友对战。' WHERE `ID` = 18364 AND `text0_0` = 'Miniature tanks, or Tonks as we\'ve cleverly named them, have been a faire favorite for as long as I can remember.$b$bWe have two arenas dedicated for tonk battles.$b$bOne arena pits you against the clock as you race to destroy targets, and avoid the enemy tonks.  You just need a game token to play!$b$bThe other arena is a place where you can use your own tonks or MiniZeps to battle your friends.';
UPDATE `npc_text` SET `text0_0` = '冲击者5000型超级大炮是一种最先进的单人抛射装置。$B$B能以近乎龙的飞行速度射出弹头，这门大炮是布莱顿海默家族的骄傲与喜悦，他们的航空与弹药技术是出了名的!$B$B如果你想要像只鸟一样在空中翱翔，就去找玛克希玛·布莱顿海默。' WHERE `ID` = 18365 AND `text0_0` = 'The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device.$b$bDelivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renowned for their aeronautical and combustible feats!$B$BIf you\'d like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer.';
UPDATE `npc_text` SET `text0_0` = '痛扁豺狼人是一个充满乐趣的游戏，让你痛扁...豺狼人。$b$b这是个新玩意，我们很多人都很爱玩。好吧，其实赛吉并不是很喜欢这个游戏。' WHERE `ID` = 18366 AND `text0_0` = 'Whack-a-Gnoll is a fun-filled game of whacking... gnolls.$b$bIt\'s a new attraction, and quite popular among us... Well, Sayge isn\'t too fond of it.';
UPDATE `npc_text` SET `text0_0` = '我们想要确保来看马戏团的观众，不管是任何年龄层，都会喜爱这些游戏。$b$b丢圈圈是一个简单的游戏，你只要试着把圈圈丢到乌龟的背上就可以了。$b$b这是我最爱的游戏之一。' WHERE `ID` = 18369 AND `text0_0` = 'We like to make sure that faire goers of all ages can enjoy the games.$b$bRing Toss is a simple game where you try to land a ring on the back of a moving turtle.$b$bIt\'s one of my favorite games to play.';
UPDATE `npc_text` SET `text0_0` = '瑞林负责经营打靶场。$b$b那里只有三个打靶的目标，命中的速度越快、分数越高。$b$b这是我最喜欢的游戏。' WHERE `ID` = 18370 AND `text0_0` = 'Rinling runs the shooting gallery.$b$bThere are only three targets to hit, and the faster you are, the better you do.$b$bPersonally, it\'s one of my favorite games.';
UPDATE `npc_text` SET `text0_0` = '我极度推荐你去拜访赛吉得到你的未来预言。我知道，我知道...他是个豺狼人。不过他是一个非常特别的豺狼人，拥有占卜你未来的能力!' WHERE `ID` = 18371 AND `text0_0` = 'I highly recommend that you visit Sayge to get your fortune told.$b$bI know, I know... he\'s a gnoll.  But he\'s a very special gnoll with the power to divine your future!';
UPDATE `npc_text` SET `text0_0` = '哈罗，$c，欢迎来到暗月马戏团。$b$b这里有很多东西可以玩，对於第一次来的参观者可能会觉得不知从何下手。我就是因为这个原因来帮忙的。$b$b你有任何疑问吗?' WHERE `ID` = 18372 AND `text0_0` = 'Hello $c, and welcome to the Darkmoon Faire.$b$bThere is so much to do here at the faire that it can be a little overwhelming for our first time visitors. That\'s why I\'m here to help.$b$bDo you have any questions?';
UPDATE `npc_text` SET `text0_0` = '把场地设置妥当还真的不简单。' WHERE `ID` = 18390 AND `text0_0` = 'This set up sure is hard work.';
UPDATE `npc_text` SET `text0_0` = '我们周遭每天都有惊奇神秘的事物，不仅仅是在暗月马戏团这里。我们整理了一份列表，是你可能平日就会碰上的惊奇事物。这本「暗月野地指南」能帮你寻找世界各地的惊奇事物。$b$b只要指南在手，你可能会碰上你前所未见的东西。有些过去你瞧不上眼的东西，说不定现在已经成为别人梦寐以求的宝物。$b$b带着这本指南，睁大你的眼睛注意各种不寻常的东西。$b$b万一你把指南搞丢了，来找我们，我们会免费再送你一本。' WHERE `ID` = 18444 AND `text0_0` = 'Mysteries and wonders surround us every day, not just at the faire.  We\'ve compiled a list of some of the wonders you may encounter in your every day business.  The Darkmoon Adventurer\'s Guide will help you navigate the wonders of the world.$b$bWith the guide in your possession, you may come across items you never knew existed.  Items you may have taken for granted in the past are now treasures that others long for.$b$bKeep the guide with you, and keep your eyes open for mystery.$b$bIf you happen to lose your guide, seek us out and we will replace it for free.';
UPDATE `npc_text` SET `text0_0` = '暗月马戏团开了!$b$b只要一点费用，我就可以把你传送到筹备区去。$b$b你想要去吗?' WHERE `ID` = 18463 AND `text0_0` = 'The Darkmoon Faire is now open!$b$bFor a small fee, I can teleport you to the fairground staging area.$b$bWould you like to go?';
UPDATE `npc_text` SET `text0_0` = '我们在等导游。' WHERE `ID` = 18559 AND `text0_0` = 'We waiting for tour guide.';
UPDATE `npc_text` SET `text0_0` = '我们等导游来吧。' WHERE `ID` = 18560 AND `text0_0` = 'We just wait for guide.';
UPDATE `npc_text` SET `text0_0` = '你是来导游的?' WHERE `ID` = 18562 AND `text0_0` = 'Are you here to lead the tour?';
UPDATE `npc_text` SET `text0_0` = '如果你不是来这里当导游的，那就走开。' WHERE `ID` = 18563 AND `text0_0` = 'If you are not here to lead a tour, leave us.';
UPDATE `npc_text` SET `text0_0` = '你准备好了吗？' WHERE `ID` = 18583 AND `text0_0` = 'Are you ready?';
UPDATE `npc_text` SET `text0_0` = '选择你的目的地。' WHERE `ID` = 18848 AND `text0_0` = 'Select your destination.';
UPDATE `npc_text` SET `text0_0` = '选择你的目的地。' WHERE `ID` = 18877 AND `text0_0` = 'Select your destination.';
UPDATE `npc_text` SET `text0_0` = '不要停啊。$B$B你还有时间可以继续玩!' WHERE `ID` = 18991 AND `text0_0` = 'Don\'t stop now.$B$BYou still have time left to play!';
UPDATE `npc_text` SET `text0_0` = '这不可能...真的结束了吗?我一定又在做梦了。' WHERE `ID` = 19021 AND `text0_0` = 'This cannot be, is it finally over?  I must be dreaming again.';
UPDATE `npc_text` SET `text0_0` = '现在你必须引领下一个年代...凡人的年代。' WHERE `ID` = 19023 AND `text0_0` = 'Now you must usher in a new age... The age of mortals.';
UPDATE `npc_text` SET `text0_0` = '欢迎，勇士们！我们所有逼她降落的尝试都失败了。我们需要帮手用这些鱼叉枪把她射下来。' WHERE `ID` = 40100 AND `text0_0` = 'Welcome, champions! All of our attempts at grounding her have failed. We could use a hand in bringing her down with these harpoon guns.';
UPDATE `npc_text` SET `text0_0` = '赞美圣光，终于有人响应了召唤。' WHERE `ID` = 40101 AND `text0_0` = 'Praise the Light, one has finally answered the calling.';
UPDATE `npc_text` SET `text0_0` = '<艾瑞斯点头>$B$B这枚眼睛见证过太多恐怖与奇迹。$B$B它会展现它认为观视者最适合看到的景象。' WHERE `ID` = 40102 AND `text0_0` = '<Eris nods>$B$BThe Eye has seen so many horrors and wonders.$B$BIt displays what it feels the one looking into it is most suited to see.';
UPDATE `npc_text` SET `text0_0` = '你就是。眼睛从不出错。$B$B毕竟你是个$c。如果眼睛向你展示了这段可怕记忆，那你定然是个强大的$c。$B$B你是为救赎而来，自己却未意识到……对吗？' WHERE `ID` = 40103 AND `text0_0` = 'You were. The Eye is never wrong.$B$BYou are a $c after all. A powerful $c, if the Eye showed you this horrible memory.$B$BYou have come for redemption, yet you yourself do not realize this... Do you?';
UPDATE `npc_text` SET `text0_0` = '我知道你会的，$N。$B$B我本人是位女祭司，但与你不同，我早已离开这个世界。然而我的灵魂仍驻留于此，还有那数千名被疯狂王子阿尔萨斯·米奈希尔及其亡灵军团残杀者的灵魂亦然。' WHERE `ID` = 40104 AND `text0_0` = 'I know you will, $N.$B$BI myself am a priestess, though, unlike you I am long since gone from this world. My spirit, however, remains here, as do the spirits of the thousands who were brutally slain by the mad Prince, Arthas Menethil and his legion of undeath.';
UPDATE `npc_text` SET `text0_0` = '我从未说过你是来救赎自己的，$c。你在此是为了救赎我，以及那些在试图逃离斯坦索姆时被谋杀的无辜者。$B$B我的灵魂与逝者的灵魂被束缚于此，被诅咒着无尽地重温我们自身惨死的瞬间。' WHERE `ID` = 40105 AND `text0_0` = 'I never stated that you were here to redeem yourself, $c. You are here to redeem me and the innocents murdered while trying to escape Stratholme.$B$BMy spirit and the spirit of those lost are bound here, cursed to endlessly relive our own tragic deaths.';
UPDATE `npc_text` SET `text0_0` = '你必须完成我未能做到之事：拯救那些在逃离斯坦索姆时被砍杀的农民。$B$B他们将走向光明，你必须确保他们存活。若倒下者过多，我们被诅咒的存在便将延续——你便失败了。$B$B你学到的每一项技能、祷言与法术都将受到考验。愿圣光庇护你，$N。' WHERE `ID` = 40106 AND `text0_0` = 'You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer and spell that you have learned will be tested. May the Light protect you, $N.';

